// Flat list of all districts across all 36 Indian States and UTs
export const ALL_DISTRICTS: LocationItem[] = INDIA_STATES_DATA.flatMap(
  (state) => state.districts
);

// Default starting district: Assam -> Dibrugarh (NER Hub)
export const DEFAULT_DISTRICT: LocationItem =
  INDIA_STATES_DATA.find((s) => s.name === 'Assam')?.districts.find(
    (d) => d.name === 'Dibrugarh'
  ) || ALL_DISTRICTS[0];

